<script setup lang="ts">const shop=useShop();const form=reactive({name:'',email:''});watchEffect(()=>{form.name=shop.user?.name||'';form.email=shop.user?.email||''});function save(){if(form.name.trim()&&/^\S+@\S+\.\S+$/.test(form.email)){shop.user={name:form.name.trim(),email:form.email};shop.saveUser();shop.notify('Demo profile updated.')}else shop.notify('Enter a name and valid email.','error')}function logout(){shop.user=null;shop.saveUser();shop.notify('Logged out of the demo.');navigateTo('/')}</script><template><div class="mx-auto w-full max-w-7xl px-4 sm:px-6 lg:px-8 py-12"><p class="text-xs font-bold uppercase tracking-[.2em] text-brand">Your space</p><h1 class="mt-2 text-4xl font-semibold tracking-tight">My account<span class="text-brand">.</span></h1><div v-if="shop.user" class="mt-8 grid gap-8 md:grid-cols-[220px_1fr]"><aside class="h-fit rounded-2xl bg-mist p-5"><p class="font-semibold">{{ shop.user.name }}</p><p class="mt-1 break-all text-xs text-gray-500">{{ shop.user.email }}</p><nav class="mt-5 flex flex-col gap-3 text-sm"><NuxtLink to="/account">Profile</NuxtLink><NuxtLink to="/account/orders">Order history ({{ shop.orders.length }})</NuxtLink><NuxtLink to="/wishlist">Wishlist</NuxtLink><button class="text-left text-red-600" @click="logout">Log out</button></nav></aside><section class="rounded-2xl border border-gray-100 p-6"><h2 class="text-lg font-semibold">Profile details</h2><p class="mt-1 text-xs text-gray-500">Changes are saved only in this browser.</p><form class="mt-6 max-w-lg space-y-4" @submit.prevent="save"><label class="block text-xs font-semibold">Name<input v-model="form.name" required class="mt-2 w-full rounded-xl border border-gray-200 px-4 py-3 text-sm"></label><label class="block text-xs font-semibold">Email<input v-model="form.email" type="email" required class="mt-2 w-full rounded-xl border border-gray-200 px-4 py-3 text-sm"></label><button class="rounded-full bg-ink px-6 py-3 text-xs font-bold uppercase tracking-wider text-white">Save changes</button></form></section></div><div v-else class="mt-8 rounded-3xl bg-mist p-8 sm:p-12"><h2 class="text-2xl font-semibold">A little space that's yours.</h2><p class="mt-3 max-w-lg text-sm leading-6 text-gray-500">Sign in to try the demo account, update profile details, and review sample orders.</p><div class="mt-6 flex gap-3"><NuxtLink to="/login" class="rounded-full bg-ink px-6 py-3 text-xs font-bold uppercase tracking-wider text-white">Demo login</NuxtLink><NuxtLink to="/register" class="rounded-full border border-gray-200 px-6 py-3 text-xs font-bold uppercase tracking-wider">Register</NuxtLink></div></div></div></template>
